#!/usr/bin/env bun
// Rebuild the vendored wallet kit the deposit page loads (issue 1615, which
// absorbed 1616): frontend/public/assets/js/vendor/rm-appkit-<version>.min.js.
//
//   bun scripts/vendor/rebuild-appkit.ts            write the bundle
//   bun scripts/vendor/rebuild-appkit.ts --check    rebuild in a temp dir and
//                                                   compare with the committed file
//   ... --check --target <path>                     compare with another file
//
// The inputs are pinned in scripts/vendor/appkit/: package.json names exact
// versions, bun.lock pins every transitive package, and entry.js lists the
// exports. The build runs in a fresh temp copy with `bun install
// --frozen-lockfile --ignore-scripts`, so a run never touches the repo's own
// node_modules. The same inputs and the same Bun give the same bytes, which is
// why the Bun version is pinned too (web-client CI runs PINNED_BUN).
//
// To upgrade: change the versions in appkit/package.json, run `bun install`
// in that directory to refresh bun.lock, delete the old bundle, run this, and
// point wallet.js at the new file name. The banner names every version, so the
// diff of a rebuild says what changed.
import { cpSync, existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const repo = join(import.meta.dir, "..", "..");
export const INPUT_DIR = join(import.meta.dir, "appkit");
export const PINNED_BUN = "1.4.4";

interface Pins { appkit: string; adapter: string; core: string; viem: string }

/** The exact versions appkit/package.json pins. */
export function readPins(dir = INPUT_DIR): Pins {
  const deps = JSON.parse(readFileSync(join(dir, "package.json"), "utf8")).dependencies as Record<string, string>;
  const exact = (name: string) => {
    const v = deps[name];
    if (!v || !/^\d+\.\d+\.\d+$/.test(v)) throw new Error(`appkit/package.json: ${name} must be an exact version, got ${v ?? "nothing"}`);
    return v;
  };
  return { appkit: exact("@reown/appkit"), adapter: exact("@reown/appkit-adapter-wagmi"), core: exact("@wagmi/core"), viem: exact("viem") };
}

/** The bundle's first line: what it is, from which versions, and how it is rebuilt. */
export function banner(p: Pins): string {
  return `/*! rm-appkit: @reown/appkit ${p.appkit} + @reown/appkit-adapter-wagmi ${p.adapter}, @wagmi/core ${p.core}, viem ${p.viem}. Built with bun ${PINNED_BUN} build --target=browser --format=esm --minify from scripts/vendor/appkit/entry.js. Rebuild: bun run vendor:appkit (scripts/vendor/rebuild-appkit.ts). Licences: MIT / Apache-2.0, see each package. */`;
}

/** Where the committed bundle lives for these pins. */
export function bundlePath(p: Pins): string {
  return join(repo, "frontend", "public", "assets", "js", "vendor", `rm-appkit-${p.appkit}.min.js`);
}

/**
 * Why `committed` is not `built`, or null when they are the same bytes. The
 * banner is compared first so a version mismatch reads as one.
 */
export function compareBundles(built: string, committed: string): string | null {
  const line = (s: string) => s.slice(0, s.indexOf("\n") === -1 ? s.length : s.indexOf("\n"));
  if (line(built) !== line(committed)) return `the version banner differs:\n  built:     ${line(built)}\n  committed: ${line(committed)}`;
  if (built === committed) return null;
  let i = 0;
  while (i < built.length && built[i] === committed[i]) i++;
  return `the generated bytes differ from byte ${i} (built ${built.length} bytes, committed ${committed.length})`;
}

async function run(cmd: string[], cwd: string): Promise<string> {
  const p = Bun.spawn(cmd, { cwd, stdout: "pipe", stderr: "pipe", env: { ...process.env, NO_COLOR: "1" } });
  const [out, err, code] = await Promise.all([new Response(p.stdout).text(), new Response(p.stderr).text(), p.exited]);
  if (code !== 0) throw new Error(`${cmd.join(" ")} exited ${code}\n${out}${err}`);
  return out;
}

/** Build the bundle from the pinned inputs in a temp dir. Returns its full text, banner included. */
export async function buildBundle(dir = INPUT_DIR): Promise<string> {
  if (Bun.version !== PINNED_BUN) throw new Error(`the bundle is pinned to bun ${PINNED_BUN}; this is bun ${Bun.version}`);
  const work = mkdtempSync(join(tmpdir(), "rm-appkit-"));
  try {
    for (const f of ["package.json", "bun.lock", "entry.js"]) cpSync(join(dir, f), join(work, f));
    await run(["bun", "install", "--frozen-lockfile", "--ignore-scripts", "--no-progress"], work);
    await run(["bun", "build", "entry.js", "--target=browser", "--format=esm", "--minify", "--outfile", "out.js"], work);
    const body = readFileSync(join(work, "out.js"), "utf8");
    return `${banner(readPins(dir))}\n${body}`;
  } finally {
    rmSync(work, { recursive: true, force: true });
  }
}

if (import.meta.main) {
  const args = process.argv.slice(2);
  const check = args.includes("--check");
  const ti = args.indexOf("--target");
  const pins = readPins();
  const target = ti === -1 ? bundlePath(pins) : args[ti + 1];
  if (!target) {
    console.error("--target needs a path");
    process.exit(2);
  }
  try {
    const built = await buildBundle();
    if (!check) {
      writeFileSync(target, built);
      console.log(`wrote ${target} (${built.length} bytes)`);
      process.exit(0);
    }
    if (!existsSync(target)) {
      console.error(`check:appkit: ${target} does not exist; run bun run vendor:appkit`);
      process.exit(1);
    }
    const why = compareBundles(built, readFileSync(target, "utf8"));
    if (why) {
      console.error(`check:appkit: ${target} is not what the pinned inputs build: ${why}\nRun bun run vendor:appkit and commit the result.`);
      process.exit(1);
    }
    console.log(`check:appkit: ${target} matches the pinned inputs (${built.length} bytes)`);
  } catch (e) {
    console.error(`check:appkit: ${(e as Error).message}`);
    process.exit(1);
  }
}
